mapper.select:
SELECT e.id AS employeeId, e.name AS employeeName, e.employee_no AS employeeNo, e.dept_id AS deptId, ar.attendance_date AS attendanceDate, ar.shift_id AS shiftId, ar.check_type AS checkType, ar.check_time AS checkTime, ar.status AS anomalyType, ar.remark AS remark, CASE ar.status WHEN 'LATE' THEN '迟到' WHEN 'EARLY' THEN '早退' WHEN 'MISSING' THEN '缺卡' ELSE ar.status END AS anomalyTypeName FROM hr_attendance_record ar INNER JOIN hr_employee e ON ar.employee_id = e.id WHERE ar.tenant_id = #{tenantId} AND ar.status IN ('LATE', 'EARLY', 'MISSING') AND ar.deleted = 0 AND e.deleted = 0
AND ar.employee_id = #{employeeId}
AND e.dept_id = #{deptId}
AND ar.status = #{anomalyType}
AND ar.attendance_date >= #{startDate}
AND ar.attendance_date <= #{endDate}
ORDER BY ar.attendance_date DESC, ar.check_time DESC
